def mno(f, x_1, x_3, epsilon):
    nombre_dor = (math.sqrt(5) + 1) / 2

    x_2 = x_3 - (x_3 - x_1) / nombre_dor
    x_4 = x_1 + (x_3 - x_1) / nombre_dor 
    while abs(x_2 - x_4) > epsilon:
        if f(x_2) < f(x_4):
            x_3 = x_4
        else:
            x_1 = x_2

        x_2 = x_3 - (x_3 - x_1) / nombre_dor
        x_4 = x_1 + (x_3 - x_1) / nombre_dor

    x_opt = (x_3 + x_1) / 2 
    return x_opt

